const docWidth = document.documentElement.scrollWidth;
const winWidth = window.innerWidth;
if (docWidth > winWidth) return false;

return true;

const controls = [
  document.getElementById('add-to-cart-btn'),
  document.getElementById('search-btn'),
  document.getElementById('site-search'),
  document.getElementById('qty-minus'),
  document.getElementById('qty-plus')
].filter(Boolean);

for (const ctrl of controls) {
  const rect = ctrl.getBoundingClientRect();
  if (rect.width < 24 || rect.height < 24) return false;

  ctrl.focus();
  if (document.activeElement !== ctrl) return false;

  const style = window.getComputedStyle(ctrl);
  const outlineWidth = parseFloat(style.outlineWidth) || 0;
  if (outlineWidth < 2) return false;
  ctrl.blur();
}
return true;

